(function(root){'use strict';const encoded={"metal":"","plate":"","punch":"","wood":"","grit":"","tap":""},cache=new Map(),RATE=22050;function sample(id){if(cache.has(id))return cache.get(id);const raw=typeof Buffer!=='undefined'?Buffer.from(encoded[id],'base64'):Uint8Array.from(atob(encoded[id]),c=>c.charCodeAt(0)),data=new Float32Array(raw.length/2);for(let i=0;i<data.length;i++){let v=raw[i*2]|raw[i*2+1]<<8;if(v>32767)v-=65536;data[i]=v/32768;}cache.set(id,data);return data;}const presets={physical:[['metal',.7],['punch',.45],['wood',.15]],pierce:[['plate',.4],['tap',.5],['punch',.3]],blunt:[['wood',.75],['punch',.6],['plate',.15]],arrow:[['tap',.8],['wood',.2]],earth:[['wood',.65],['grit',.25],['tap',.35]],critical:[['plate',.5],['wood',.3],['punch',.3]]};function effect(key){const kind=key.split('-')[0],parts=presets[kind];if(!parts)return null;const all=key.endsWith('-all'),duration=(kind==='arrow'?.34:kind==='earth'?.62:.48)+(all?.13:0),data=new Float32Array(Math.ceil(duration*RATE));let low=0,dc=0;const alpha=1-Math.exp(-2*Math.PI*(kind==='blunt'?2600:3500)/RATE),sources=parts.map(([id,gain])=>[sample(id),gain]);for(let i=0;i<data.length;i++){let v=0;for(const [src,gain]of sources){v+=(src[i]||0)*gain;if(all)v+=(src[i-1764]||0)*gain*.35;}dc+=.016*(v-dc);low+=alpha*(v-dc-low);data[i]=Math.tanh(low*1.25)*.8*Math.min(1,(data.length-i)/160);}return {data,sampleRate:RATE,duration};}const api={effect,sample};root.BattleFoley=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;})(globalThis);
